import{_ as e,o as r,c as o,ag as a}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"Versions and compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"docs/versions.md","filePath":"docs/versions.md"}'),i={name:"docs/versions.md"};function d(n,t,s,c,l,m){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="versions-and-compatibility" tabindex="-1">Versions and compatibility <a class="header-anchor" href="#versions-and-compatibility" aria-label="Permalink to &quot;Versions and compatibility&quot;">​</a></h1><p>Takoform has two domain version axes: API/Core release SemVer and each Form&#39;s <code>definitionVersion</code>. Provider SemVer, package/schema IDs and digests, and withdrawn lanes identify artifacts or history; they do not add a domain axis.</p><h2 id="current-identities" tabindex="-1">Current identities <a class="header-anchor" href="#current-identities" aria-label="Permalink to &quot;Current identities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Identity</th><th>Use</th></tr></thead><tbody><tr><td>API/Core</td><td><strong><code>v1.0.1</code></strong></td><td>Current compatibility checkpoint on <code>forms.takoform.com/v1</code>; compatible 1.x checkpoints stay on that lane.</td></tr><tr><td>External Edge publication</td><td><a href="https://github.com/tako0614/takoform-forms/commit/3231633605b737ce5279d7fc020b4780568e7091" target="_blank" rel="noreferrer"><code>takoform-forms</code> at commit <code>3231633605b737ce5279d7fc020b4780568e7091</code></a></td><td>Publication authority for 17 content-addressed packages.</td></tr><tr><td>Embedded Edge candidate snapshot</td><td><a href="/forms/candidates/edge.forms.takoform.com/candidate-set.json"><code>forms/candidates/edge.forms.takoform.com/candidate-set.json</code></a></td><td>Provider-repository snapshot with <code>publicationStatus: unpublished</code>; not publication evidence.</td></tr><tr><td>Provider</td><td><strong><code>4.0.0</code></strong></td><td>Registry-published at the <code>tako0614/takoform</code> source address, with only the 17 tako0614 Edge mappings.</td></tr><tr><td>Form Package envelope</td><td><code>packages.forms.takoform.com/v1alpha5</code></td><td>Package identity; publication is independent of Provider release.</td></tr></tbody></table><p>An exact Form is identified by its family, kind, <code>definitionVersion</code>, and <code>schemaDigest</code>. Generated resource pages link the corresponding Form Definition and retain this identity in state; a Provider resource name is only adapter metadata.</p><h2 id="provider-compatibility-history" tabindex="-1">Provider compatibility history <a class="header-anchor" href="#provider-compatibility-history" aria-label="Permalink to &quot;Provider compatibility history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Host/API lane</th><th>Compatibility</th></tr></thead><tbody><tr><td><strong>4.0.0</strong></td><td>Current Host API</td><td>Current Registry-published publisher-set 17-Form Edge mapping.</td></tr><tr><td><strong>3.0.0</strong></td><td>Current Host API</td><td>Immutable retained 31-Form aggregate Registry distribution.</td></tr><tr><td><strong>2.1.1</strong></td><td><code>forms.takoform.com/v1beta1</code></td><td>Retained client for 15 immutable Edge Form identities in the <a href="/release/provider-form-identities.json">identity ledger</a>.</td></tr><tr><td><strong>2.0.0</strong></td><td>Withdrawn <code>v1alpha2</code> epoch</td><td>Immutable Registry history; exact-pin recovery and migration only.</td></tr><tr><td><strong>1.0.3</strong></td><td>Withdrawn <code>v1alpha1</code> epoch</td><td>Immutable Registry history; exact-pin recovery and migration only.</td></tr></tbody></table><p>Provider releases are independent of Form definition and package publication. For state created by a withdrawn Provider epoch, follow the <a href="/release/migrations/v2-to-v3.html">v2-to-v3 migration boundary</a>. For the publisher-set cut, follow the <a href="/release/migrations/v3-to-v4.html">v3-to-v4 boundary</a>. No automatic migration occurs.</p><h2 id="related-references" tabindex="-1">Related references <a class="header-anchor" href="#related-references" aria-label="Permalink to &quot;Related references&quot;">​</a></h2><ul><li><a href="/docs/">Provider resource reference</a></li><li><a href="/forms/">Provider mapping inventory</a></li><li><a href="/release/">Specification and release evidence</a></li><li><a href="/conformance/">Conformance evidence</a></li></ul>',10)])])}const f=e(i,[["render",d]]);export{p as __pageData,f as default};
